int parent[MAXN], order[MAXN];
int f[MAXN], g[MAXN];

void addEdge(int u, int v) {
    to[++ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

int check(int R) {
    for (int i = 1; i <= N; ++i) {
        f[i] = 0;
        g[i] = INF;
    }

    int count = 0;

    for (int idx = N; idx >= 1; --idx) {
        int u = order[idx];

        if (f[u] >= 0 && g[u] < INF && f[u] + g[u] <= R) {
            f[u] = NEG;
        }

        if (f[u] == R) {
            ++count;
            g[u] = 0;
            f[u] = NEG;
        }

        if (u != 1) {
            int p = parent[u];

            if (f[u] >= 0) {
                int val = f[u] + 1;
                if (val > f[p]) f[p] = val;
            }

            if (g[u] < INF) {
                int val = g[u] + 1;
                if (val < g[p]) g[p] = val;
            }
        }
    }

    if (f[1] >= 0) ++count;

    return count <= K;
}

static char buf[1 << 20];
static int buf_idx = 0, buf_len = 0;

int readChar() {
    if (buf_idx >= buf_len) {
        buf_len = fread(buf, 1, sizeof(buf), stdin);
        buf_idx = 0;
        if (buf_len == 0) return -1;
    }
